    expect(described_class.write!(snapshots:, version: 1, generation: 2)).to eq(2)

    ids.each do |id|
      expect(OutboxSnapshot.where(id:, generation: 2).pluck(:version, :source)).to eq([[1, "manual"]])
    end
  end
